exec tool declaration:
```ts
declare const tools: { mcp__pixellab__animate_object(args: {
  // The motion, e.g. 'walking cheerfully'. Required for a new animation; inherited when adding directions via animation_group_id.
  animation_description?: string | null;
  // An existing animation's id (from get_object) to add directions to it; omit to start a new one (its id is returned).
  animation_group_id?: string | null;
  // pro only. Never true on the first call, which returns the cost to show the user; re-call with true only after they confirm.
  confirm_cost?: boolean;
  // v3/pixminimax: a start pose instead of the object's idle frame; its size sets the canvas (max 256x256). 8-direction objects: ONE direction, the one the user names (ask; never pick one).
  custom_start_frame_base64?: string | null;
  // v3/pixminimax, 8-direction objects: one description per direction, all eight keys; animation_description may then be left out. Reused when adding directions to the animation.
  direction_prompts?: { [key: string]: string; } | null;
  // 8-direction objects only (a 1-direction object refuses it). Omit for all 8, or, with animation_group_id, for the ones it is missing.
  directions?: Array<"south" | "south-west" | "west" | "north-west" | "north" | "north-east" | "east" | "south-east"> | null;
  // Optional name for the animation, shown in the UI and used when exporting.
  display_name?: string | null;
  // v3/pixminimax: a pose to animate toward, same size as the start frame. One direction, as for custom_start_frame_base64.
  end_frame_base64?: string | null;
  // Omit for the mode's default (8; pro: the smallest its canvas allows). v3: even, 4-16. pixminimax: a multiple of 4, 4-40. pro: 16 up to 64px, 4/9/16 up to 128px, 9 up to 170px.
  frame_count?: number | null;
  // v3/pixminimax: keep the start frame as frame 0 (frame_count + 1 stored); false stores exactly frame_count.
  keep_first_frame?: boolean;
