  // Tile index in the layer's tile group. Left out on a building kit's interior-wall and roof layers, whose pieces follow their neighbours
  tile?: number | null;
} | {
  // An inclusive block of cells: q..q+width-1, r..r+height-1.
  area?: { height: number; q: number; r: number; width: number; } | null;
  cells?: Array<Array<number>> | null;
