declare const tools: { mcp__pixellab__transfer_outfit(args: {
  // Optional guidance for the transfer, e.g. 'frames show the character from behind' or 'keep the sword in the right hand'.
  additional_instructions?: string | null;
  // Alternative to frames_base64: https, data: or `upload:<id>` (POST /v2/uploads with this same bearer token) URLs to the frame PNGs, in order. PREFER THIS for anything but tiny sprites. Give urls OR base64, not both.
  frame_urls?: Array<string> | null;
  // Base64 PNG animation frames to reskin, in order (2 or more). Max 256x256 each. PREFER frame_urls — MCP clients routinely truncate large inline base64.
  frames_base64?: Array<string> | null;
  // Output frame height. Defaults to the tallest frame.
  height?: number | null;
  // At most this many colours (2-64). With a palette, they are picked from it. On the three tools that have a standard mode — create_character, create_topdown_tileset, animate_object — ANY palette setting needs mode='pro': standard refuses palette and max_colors, alone or together. Every other tool taking them has no standard mode and accepts them always.
  max_colors?: number | null;
  // Background handling. Default (unset) follows the frames: if any frame has transparency the results are transparent, otherwise opaque. Pass False to flatten a transparent input onto white.
  no_background?: boolean | null;
  // Target palette, 2 to 256 hex colours as a JSON array, e.g. ["#081820", "#346856", "#88c070", "#e0f8d0"] for Game Boy or ["#000000", "#ffffff"] for 1-bit. Every pixel the tool draws is one of them; pixels you supplied (a direction you drew) stay as they are.
  palette?: Array<string> | null;
  // Optional name of the palette (e.g. 'Game Boy', 'PICO-8'); naming it helps the look. It only LABELS the colours you pass in palette rather than looking any up, so it cannot be sent on its own.
  palette_name?: string | null;
  // Internal Game Builder project context; the finished frames are linked after generation.
  project_id?: string | null;
  // Base64 PNG of the SAME character wearing the new outfit (e.g. a re-dressed or recoloured sprite of it). A different character as reference is unreliable — it can freeze the motion or barely change anything. Max 256x256.
  reference_image_base64?: string | null;
  // Alternative to reference_image_base64: an https, data: or `upload:<id>` URL to the reference PNG. PREFER THIS for anything but a tiny sprite. Give one, not both.
  reference_image_url?: string | null;
  // Seed for reproducible generation.
  seed?: number | null;
  // Output frame width. Defaults to the widest frame. Frames and reference smaller than this are padded with transparency, centred — never scaled.
  width?: number | null;
}): Promise<CallToolResult>; };
